519	func TestInvalidConfigUnbracketedIPv6Host(t *testing.T) {
520		// An IPv6 literal is an IP-literal and must be wrapped in one pair of
521		// square brackets; a bare literal leaves the host/port boundary undefined
522		// (with "::1:8080" the reader cannot tell the host from a port) and the
523		// reader never inserts brackets or guesses a port. Every IPv6 spelling
524		// rejects the whole configuration as invalid_config with a content reason
525		// naming the route's 1-based position, its id and the upstream field — a
526		// digit at the end never makes the spelling legal, and this is never a
527		// broken-JSON failure.
528		badUpstreams := []struct {
529			name     string
530			upstream string
531		}{
532			{"compressed address under base path", "http://2001:db8::1/base"},
533			{"compressed address with trailing digits", "http://::1:8080/base"},
534			{"embedded ipv4 tail", "http://::ffff:192.0.2.1/base"},
535			{"full form", "http://2001:0db8:0000:0000:0000:0000:0000:0001/base"},
536			{"loopback with no base path", "http://::1"},
537			{"address and trailing digits, no base path", "http://fe80::1:8080"},
538			{"percent encoded zone without brackets", "http://fe80::1%25eth0/base"},
539			{"userinfo before a bare literal", "http://user:pw@2001:db8::1/base"},
540			{"encoded userinfo and a port-like suffix", "https://user:p%40ss@2001:db8::1:8443/base"},
541		}
542		for _, tc := range badUpstreams {
543			t.Run(tc.name, func(t *testing.T) {
544				src := `{"routes":[
545				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
546				  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
547				]}`
548				cfg, f := ParseConfig([]byte(src))
549				if f == nil {
550					t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
551				}
552				if f.Code != "invalid_config" {
553					t.Fatalf("code = %q, want invalid_config", f.Code)
554				}
555				for _, want := range []string{"route 2", `"admin"`, "upstream", "IPv6", "bracket"} {
556					if !strings.Contains(f.Reason, want) {
557						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
558					}
559				}
560				if strings.Contains(f.Reason, "not valid JSON") {
561					t.Fatalf("an unbracketed IPv6 host is a content error, not a JSON syntax failure: %q", f.Reason)
562				}
563				if cfg != nil {
564					t.Fatalf("a rejected config must not be returned, got %+v", cfg)
565				}
566			})
567		}
568	
569		// The offending route may be one the request never hits: config
570		// validation still fails up front (and hands back no config at all)
571		// instead of letting the first, valid route resolve the request.
572		for _, up := range []string{"http://2001:db8::1/base", "http://::1:8080/base", "http://::ffff:192.0.2.1/base"} {
573			src := `{"routes":[
574			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
575			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + up + `"}
576			]}`
577			cfg, f := ParseConfig([]byte(src))
578			if f == nil || f.Code != "invalid_config" {
579				t.Fatalf("upstream %q: got %+v, want invalid_config", up, f)
580			}
581			if cfg != nil {
582				t.Fatalf("upstream %q: a rejected config must not be returned", up)
583			}
584		}
585	}
