587	func TestUnbracketedNonIPv6AuthoritiesUnaffected(t *testing.T) {
588		// Ordinary domains and bare IPv4 hosts keep their existing behavior with
589		// or without a port, and colons inside userinfo or the base path must not
590		// turn a legal host into a flagged IPv6 literal. Each upstream must both
591		// parse and join the remainder byte for byte.
592		cases := []struct {
593			name     string
594			upstream string
595			target   string
596			want     string
597		}{
598			{"plain domain", "http://api.internal/v1", "/x", "http://api.internal/v1/x"},
599			{"domain with port", "http://api.internal:8080/v1", "/x", "http://api.internal:8080/v1/x"},
600			{"bare ipv4", "http://192.0.2.1/base", "/x", "http://192.0.2.1/base/x"},
601			{"bare ipv4 with port", "http://192.0.2.1:8080/base", "/x", "http://192.0.2.1:8080/base/x"},
602			{"colon in userinfo", "http://user:pa:ss@h.internal:8080/base", "/x", "http://user:pa:ss@h.internal:8080/base/x"},
603			{"colon in base path", "http://h.internal/base/a:b/c", "/x", "http://h.internal/base/a:b/c/x"},
604			{"localhost without port", "http://localhost/base", "/x", "http://localhost/base/x"},
605		}
606		for _, tc := range cases {
607			t.Run(tc.name, func(t *testing.T) {
608				src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"` + tc.upstream + `"}]}`
609				cfg := mustConfig(t, src)
610				res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
611				if res.RouteID != "r" {
612					t.Errorf("routeId = %q, want r", res.RouteID)
613				}
614				if res.UpstreamURL != tc.want {
615					t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.want)
