16	// These tests exercise resolve the way a user does: a config file argument,
17	// one JSON request on stdin, and the observable exit status / stdout / stderr
18	// of the whole command. They never open a network connection and do not need
19	// the upstreams to exist, so they reproduce deterministically offline.
20	
21	// helperEnv guards TestHelperProcess: only a child spawned with this variable
22	// set hands its arguments over to the real main; in an ordinary `go test`
23	// run the test is a no-op.
24	const helperEnv = "CONTRACTSENTINEL_HELPER_PROCESS"
25	
26	// TestHelperProcess is the re-executed test binary: arguments after "--"
27	// become the command's own os.Args, then main runs as normal (including its
28	// non-zero os.Exit on failure, which the parent observes via exit status).
29	func TestHelperProcess(t *testing.T) {
30		if os.Getenv(helperEnv) != "1" {
31			return
32		}
33		for i, a := range os.Args {
34			if a == "--" {
35				os.Args = append([]string{os.Args[0]}, os.Args[i+1:]...)
36				break
37			}
38		}
39		main()
40		os.Exit(0)
41	}
42	
43	// resolveResult is everything the parent can observe from one resolve run.
44	type resolveResult struct {
45		stdout   []byte
46		stderr   []byte
47		exitCode int
48	}
49	
50	// runResolveCLI writes config to a temp file, spawns the helper test binary
51	// with "resolve <config>" and feeds the request on stdin.
52	func runResolveCLI(t *testing.T, config, request string) resolveResult {
53		t.Helper()
54	
55		dir := t.TempDir()
56		configPath := filepath.Join(dir, "config.json")
57		if err := os.WriteFile(configPath, []byte(config), 0o600); err != nil {
58			t.Fatalf("write config: %v", err)
59		}
60	
61		cmd := exec.Command(os.Args[0], "-test.run=^TestHelperProcess$", "--", "resolve", configPath)
62		cmd.Env = append(os.Environ(), helperEnv+"=1")
63		cmd.Stdin = strings.NewReader(request)
64		var stdout, stderr bytes.Buffer
65		cmd.Stdout = &stdout
66		cmd.Stderr = &stderr
67	
68		err := cmd.Run()
69		exitCode := 0
70		if err != nil {
71			var exitErr *exec.ExitError
72			if errors.As(err, &exitErr) {
73				exitCode = exitErr.ExitCode()
74			} else {
75				t.Fatalf("run resolve helper: %v", err)
76			}
77		}
78		return resolveResult{stdout: stdout.Bytes(), stderr: stderr.Bytes(), exitCode: exitCode}
79	}
80	
81	// decodeOneJSON decodes exactly one JSON value and requires nothing but
82	// trailing whitespace afterwards, so "one JSON object in the stream" is
83	// asserted instead of merely "a prefix parses".
84	func decodeOneJSON(t *testing.T, data []byte, what string, v any) {
85		t.Helper()
86		dec := json.NewDecoder(bytes.NewReader(data))
87		if err := dec.Decode(v); err != nil {
88			t.Fatalf("%s is not a single JSON object: %v\n%s", what, err, data)
89		}
90		if err := dec.Decode(&struct{}{}); err != io.EOF {
91			t.Fatalf("%s contains more than one JSON value: %v\n%s", what, err, data)
92		}
93	}
