			for _, want := range []string{"route 2", `"admin"`, "upstream", "IPv6", "bracket"} {
				if !strings.Contains(fail.Reason, want) {
					t.Errorf("reason = %q, want substring %q", fail.Reason, want)
				}
			}
			if strings.Contains(fail.Reason, "not valid JSON") {
