	if p.schemeEnd < 0 {
		return nil // no scheme: the generic absolute-URL check reports this
	}
	hostPort := p.hostPort
	if hostPort == "" || strings.ContainsAny(hostPort, "[]") {
		// No host (the generic check reports it) or a bracketed literal,
		// which the bracketed-host validator owns.
		return nil
	}

	// A single colon is the legal host/port separator ("host:8080"); zero
	// colons is a bare host. Count raw colons only: percent-encoded colons
	// ("%3A") carry no separator byte, and userinfo and the base path were
	// sliced off by splitUpstream.
	if strings.Count(hostPort, ":") <= 1 {
		return nil
	}
	label := routeLabel(loc, id)

	// A trailing ":<digits>" might look like a port; test the address
	// without it as well so an unbracketed address with a port-like suffix
	// ("fe80::1:8080") still gets the missing-brackets reason rather than
	// the generic extra-colon one. The suffix is only stripped once: a real
	// bare IPv6 literal without a port is tested first and identified anyway.
	candidates := []string{hostPort}
	if i := strings.LastIndexByte(hostPort, ':'); i >= 0 && isDigits(hostPort[i+1:]) {
		candidates = append(candidates, hostPort[:i])
	}
